(function(){angular.module("app.core").controller("MsFormWizardController",MsFormWizardController).directive("msFormWizard",msFormWizardDirective).directive("msFormWizardForm",msFormWizardFormDirective);function MsFormWizardController(){var vm=this;vm.forms=[];
vm.selectedIndex=0;vm.registerForm=registerForm;vm.previousStep=previousStep;vm.nextStep=nextStep;vm.firstStep=firstStep;vm.lastStep=lastStep;vm.totalSteps=totalSteps;vm.isFirstStep=isFirstStep;vm.isLastStep=isLastStep;vm.currentStepInvalid=currentStepInvalid;
vm.previousStepInvalid=previousStepInvalid;vm.formsIncomplete=formsIncomplete;vm.resetForm=resetForm;function registerForm(form){vm.forms.push(form)}function previousStep(){if(isFirstStep()){return}vm.selectedIndex--}function nextStep(){if(isLastStep()){return
}vm.selectedIndex++}function firstStep(){vm.selectedIndex=0}function lastStep(){vm.selectedIndex=totalSteps()-1}function totalSteps(){return vm.forms.length}function isFirstStep(){return vm.selectedIndex===0}function isLastStep(){return vm.selectedIndex===totalSteps()-1
}function currentStepInvalid(){return angular.isDefined(vm.forms[vm.selectedIndex])&&vm.forms[vm.selectedIndex].$invalid}function previousStepInvalid(){return vm.selectedIndex>0&&angular.isDefined(vm.forms[vm.selectedIndex-1])&&vm.forms[vm.selectedIndex-1].$invalid
}function formsIncomplete(){for(var x=0;x<vm.forms.length;x++){if(vm.forms[x].$invalid){return true}}return false}function resetForm(){vm.selectedIndex=0;for(var x=0;x<vm.forms.length;x++){vm.forms[x].$setPristine();vm.forms[x].$setUntouched()}}}function msFormWizardDirective(){return{restrict:"E",scope:true,controller:"MsFormWizardController as msWizard",compile:function(tElement){tElement.addClass("ms-form-wizard");
return function postLink(){}}}}function msFormWizardFormDirective(){return{restrict:"A",require:["form","^msFormWizard"],compile:function(tElement){tElement.addClass("ms-form-wizard-form");return function postLink(scope,iElement,iAttrs,ctrls){var formCtrl=ctrls[0],MsFormWizardCtrl=ctrls[1];
MsFormWizardCtrl.registerForm(formCtrl)}}}}})();